#!/usr/bin/env python3
"""Render an event announcement HWPX from a template and JSON data.

- Replaces all {{...}} placeholders in ALL text-like files inside the HWPX ZIP.
- For any <hp:p> paragraph whose content changed due to placeholder replacement,
  removes any <hp:linesegarray> (or unprefixed <linesegarray>) within that
  paragraph to avoid stale layout caches.

Output: /root/event_announcement_ready.hwpx
"""

from __future__ import annotations

import json
import re
import zipfile
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Dict, Iterable, List, Tuple

TEMPLATE_PATH = Path("/root/event_announcement_template.hwpx")
DATA_PATH = Path("/root/event_data.json")
OUT_PATH = Path("/root/event_announcement_ready.hwpx")

PLACEHOLDER_RE = re.compile(r"\{\{([^}]+)\}\}")


def flatten_json(value: Any, prefix: str = "") -> Dict[str, Any]:
    """Flatten nested JSON-like structures.

    Rules:
      - dict: keys join with '.'
      - list: indexed keys via '.0', '.1', ...

    Also stores a direct key for the prefix itself when prefix is non-empty,
    so a list can still be referenced by its name (stringified).
    """

    out: Dict[str, Any] = {}

    def add(k: str, v: Any) -> None:
        if not k:
            return
        out[k] = v

    if isinstance(value, dict):
        for k, v in value.items():
            k = str(k)
            child_prefix = f"{prefix}.{k}" if prefix else k
            out.update(flatten_json(v, child_prefix))
    elif isinstance(value, list):
        # Allow direct reference to the list key as a newline-joined string
        if prefix:
            add(prefix, "\n".join(stringify(x) for x in value))
        for i, item in enumerate(value):
            child_prefix = f"{prefix}.{i}" if prefix else str(i)
            out.update(flatten_json(item, child_prefix))
    else:
        add(prefix, value)

    return out


def stringify(v: Any) -> str:
    if v is None:
        return ""
    if isinstance(v, (str, int, float, bool)):
        return str(v)
    # Fallback for dict/list: keep deterministic JSON.
    return json.dumps(v, ensure_ascii=False, separators=(",", ":"))


@dataclass
class ReplacementStats:
    # placeholder -> count
    counts: Dict[str, int]
    # file -> number of replacements
    file_counts: Dict[str, int]
    # (file, para_id) for paragraphs where linesegarray was removed
    lineseg_removed: List[Tuple[str, str]]


def is_text_file(name: str) -> bool:
    lower = name.lower()
    return lower.endswith((".xml", ".rels", ".txt", ".html", ".htm"))


def clone_zipinfo(src: zipfile.ZipInfo) -> zipfile.ZipInfo:
    # Create a new ZipInfo and copy relevant metadata.
    dst = zipfile.ZipInfo(filename=src.filename, date_time=src.date_time)
    dst.compress_type = src.compress_type
    dst.comment = src.comment
    dst.extra = src.extra
    dst.create_system = src.create_system
    dst.create_version = src.create_version
    dst.extract_version = src.extract_version
    dst.flag_bits = src.flag_bits
    dst.internal_attr = src.internal_attr
    dst.external_attr = src.external_attr
    dst.volume = getattr(src, "volume", 0)
    return dst


def replace_placeholders_in_text(
    text: str,
    mapping: Dict[str, Any],
    stats: ReplacementStats | None = None,
    file_name: str | None = None,
) -> str:
    def repl(m: re.Match[str]) -> str:
        key = m.group(1).strip()
        if key in mapping:
            val = mapping[key]
        else:
            # fallbacks: try raw key as-is, and try stripping surrounding spaces
            val = mapping.get(key)

        if stats is not None:
            stats.counts[key] = stats.counts.get(key, 0) + 1
            if file_name is not None:
                stats.file_counts[file_name] = stats.file_counts.get(file_name, 0) + 1

        return stringify(val)

    return PLACEHOLDER_RE.sub(repl, text)


P_BLOCK_RE = re.compile(r"(<hp:p\b[^>]*>.*?</hp:p>)", re.DOTALL)


def strip_linesegarray(xml_fragment: str) -> str:
    # Remove both namespaced and unprefixed variants.
    xml_fragment = re.sub(
        r"<hp:linesegarray\b[^>]*>.*?</hp:linesegarray>",
        "",
        xml_fragment,
        flags=re.DOTALL,
    )
    xml_fragment = re.sub(
        r"<linesegarray\b[^>]*>.*?</linesegarray>",
        "",
        xml_fragment,
        flags=re.DOTALL,
    )
    return xml_fragment


def get_para_id(p_block: str) -> str:
    m = re.search(r"\bid=\"([^\"]+)\"", p_block)
    return m.group(1) if m else ""


def render_xml_with_paragraph_sensitive_lineseg_removal(
    xml: str,
    mapping: Dict[str, Any],
    stats: ReplacementStats,
    file_name: str,
) -> str:
    """Replace placeholders in an XML string.

    - Replacements are done per <hp:p> block.
    - If a block changes, strip <*linesegarray> from that block only.
    """

    parts: List[str] = []
    last = 0
    for m in P_BLOCK_RE.finditer(xml):
        start, end = m.span(1)
        # outside paragraphs: still do placeholder replacement, but don't touch layout caches
        outside = xml[last:start]
        if "{{" in outside:
            outside = replace_placeholders_in_text(outside, mapping, stats=stats, file_name=file_name)
        parts.append(outside)

        p_block = m.group(1)
        original_block = p_block
        if "{{" in p_block:
            p_block = replace_placeholders_in_text(p_block, mapping, stats=stats, file_name=file_name)

        if p_block != original_block:
            para_id = get_para_id(original_block)
            p_block = strip_linesegarray(p_block)
            stats.lineseg_removed.append((file_name, para_id))

        parts.append(p_block)
        last = end

    tail = xml[last:]
    if "{{" in tail:
        tail = replace_placeholders_in_text(tail, mapping, stats=stats, file_name=file_name)
    parts.append(tail)

    rendered = "".join(parts)

    # If we still see any braces but no full placeholder pattern, that suggests split placeholders.
    # In that case, fail loudly rather than silently producing a broken document.
    if ("{{" in rendered or "}}" in rendered) and not PLACEHOLDER_RE.search(rendered):
        raise RuntimeError(
            f"Detected brace tokens but no complete placeholders after rendering {file_name}; "
            "this suggests placeholders may be split across tags. "
            "Implementing a tag-merge fallback is required for this template."
        )

    return rendered


def main() -> None:
    if not TEMPLATE_PATH.exists():
        raise SystemExit(f"Missing template: {TEMPLATE_PATH}")
    if not DATA_PATH.exists():
        raise SystemExit(f"Missing data: {DATA_PATH}")

    data = json.loads(DATA_PATH.read_text(encoding="utf-8"))

    flat = flatten_json(data)
    mapping: Dict[str, Any] = {}
    # Keep both flattened keys and original unflattened top-level keys.
    mapping.update(flat)
    if isinstance(data, dict):
        mapping.update(data)

    stats = ReplacementStats(counts={}, file_counts={}, lineseg_removed=[])

    # Scan placeholders first (for reporting / safety)
    placeholders: Dict[str, List[str]] = {}
    with zipfile.ZipFile(TEMPLATE_PATH, "r") as zin:
        for name in zin.namelist():
            if not is_text_file(name):
                continue
            raw = zin.read(name)
            try:
                txt = raw.decode("utf-8")
            except UnicodeDecodeError:
                continue
            found = sorted({m.group(1).strip() for m in PLACEHOLDER_RE.finditer(txt)})
            if found:
                placeholders[name] = found

    # Render and write output
    with zipfile.ZipFile(TEMPLATE_PATH, "r") as zin, zipfile.ZipFile(OUT_PATH, "w") as zout:
        for name in zin.namelist():
            info = zin.getinfo(name)
            src_bytes = zin.read(name)
            out_bytes = src_bytes

            if is_text_file(name):
                try:
                    txt = src_bytes.decode("utf-8")
                except UnicodeDecodeError:
                    txt = None

                if txt is not None and ("{{" in txt or "}}" in txt):
                    if name.lower().endswith(".xml"):
                        rendered = render_xml_with_paragraph_sensitive_lineseg_removal(
                            txt, mapping=mapping, stats=stats, file_name=name
                        )
                    else:
                        rendered = replace_placeholders_in_text(txt, mapping, stats=stats, file_name=name)

                    out_bytes = rendered.encode("utf-8")

            out_info = clone_zipinfo(info)
            zout.writestr(out_info, out_bytes)

    # Validation
    with zipfile.ZipFile(OUT_PATH, "r") as z:
        bad: List[Tuple[str, str]] = []
        for name in z.namelist():
            if not name.lower().endswith(".xml"):
                continue
            raw = z.read(name)
            try:
                txt = raw.decode("utf-8")
            except UnicodeDecodeError:
                continue
            if PLACEHOLDER_RE.search(txt):
                bad.append((name, "has {{...}} placeholders"))
            # Also catch any raw brace leftovers.
            if "{{" in txt or "}}" in txt:
                # If braces remain, they must be literal; for this task, we treat it as an error.
                bad.append((name, "has leftover brace tokens"))

        # Check a couple of expected static lines are preserved.
        section0 = None
        if "Contents/section0.xml" in z.namelist():
            section0 = z.read("Contents/section0.xml").decode("utf-8")
            for must in ["행사 공지문", "비고: 사전 신청 필수"]:
                if must not in section0:
                    bad.append(("Contents/section0.xml", f"missing expected static text: {must}"))

        # Ensure linesegarray removed from paragraphs that had placeholders.
        if section0 is not None:
            # If any linesegarray still exists, it must only be in paragraphs that were not modified.
            if "linesegarray" in section0:
                # Conservative: for this template, all placeholder paragraphs should have had it removed.
                # We at least ensure that paragraphs containing any of the replaced values do not contain linesegarray.
                for k, v in mapping.items():
                    sv = stringify(v)
                    if not sv:
                        continue
                    if sv in section0:
                        # find the paragraph block containing this value and ensure it has no linesegarray
                        for pm in P_BLOCK_RE.finditer(section0):
                            block = pm.group(1)
                            if sv in block and "linesegarray" in block:
                                bad.append(("Contents/section0.xml", f"linesegarray still present in modified paragraph containing value for {k}"))
                                break

        if bad:
            print("VALIDATION: FAIL")
            for name, msg in bad:
                print(f" - {name}: {msg}")
            raise SystemExit(2)

    # Summary
    print("Render complete:")
    print(f" - template: {TEMPLATE_PATH}")
    print(f" - data:     {DATA_PATH}")
    print(f" - output:   {OUT_PATH}")
    print("\nPlaceholders seen by file:")
    for fn, ph in sorted(placeholders.items()):
        print(f" - {fn}: {', '.join(ph)}")

    print("\nReplacement counts:")
    for k in sorted(stats.counts):
        print(f" - {k}: {stats.counts[k]}")

    print("\nFiles modified (replacement hits):")
    for fn in sorted(stats.file_counts):
        print(f" - {fn}: {stats.file_counts[fn]}")

    print("\nParagraphs with linesegarray removed:")
    for fn, pid in stats.lineseg_removed:
        print(f" - {fn} para_id={pid}")

    print("\nVALIDATION: OK (no remaining {{...}} placeholders)")


if __name__ == "__main__":
    main()

